from collections import defaultdict
from typing import List


def resolve_battles(actions: List[str]) -> List[str]:
    armies = []  # (name, loc, kind, arg) in input order
    for act in actions:
        t = act.split()
        armies.append((t[0], t[1], t[2], t[3] if len(t) > 3 else None))

    attacked = {arg for _, _, kind, arg in armies if kind == "Move"}
    strength = {name: 1 for name, *_ in armies}
    for name, loc, kind, arg in armies:
        if kind == "Support" and loc not in attacked and arg in strength:
            strength[arg] += 1

    at = defaultdict(list)  # landing location -> armies
    for name, loc, kind, arg in armies:
        at[arg if kind == "Move" else loc].append(name)

    final = {}
    for loc, group in at.items():
        best = max(strength[a] for a in group)
        top = [a for a in group if strength[a] == best]
        for a in group:
            final[a] = loc if len(top) == 1 and a == top[0] else "[dead]"
    return [f"{name} {final[name]}" for name, *_ in armies]
